"""PSLE-style items for sci-energy-heat-effects (file sci-heat-effects.json), all tiers (round sci-fill-heat-effects-2026-11-20)."""
from fillkit import add, table, graph, lint, ship
from figs_heat import thermometer, rods, ball_ring, flask_tube, balloon, touching, bath

SUB, FILE = "sci-energy-heat-effects", "sci-heat-effects.json"
HE, FT, RD = "sci-pat-heat-effects-conductors", "sci-pat-fair-test-design", "sci-pat-read-data"
B, I, C = "basic", "intermediate", "competent"
P = []
def q(*a): P.append(a)
def W(t, tag, why): return (t, tag, why)
def tb(h, r, w, c): return lambda: table(h, r, w, c)
D = "°C"

# ---------------- basic ----------------
q("he-001", B, 2, HE, "Which of the following is a good conductor of heat?", "A steel spoon", [W("A wooden spoon", "wrong-material", "Wood is a poor conductor of heat."), W("A plastic cup", "wrong-material", "Plastic is a poor conductor of heat."), W("A rubber band", "wrong-material", "Rubber is a poor conductor of heat.")], ["Metals such as steel are good conductors of heat."], None)
q("he-002", B, 2, HE, "Why are cooking pots usually made of metal?", "Metal is a good conductor, so heat reaches the food quickly", [W("Metal is a poor conductor, so heat stays inside the pot", "reversed", "Metal is a good conductor of heat."), W("Metal does not gain any heat from the stove", "wrong-idea", "Metal gains heat from the stove quickly."), W("Metal is a good insulator of heat", "reversed", "A good insulator is a poor conductor. Metal conducts heat well.")], ["A metal pot conducts heat from the stove to the food."], None)
q("he-003", B, 2, HE, "The handle of a pot is made of plastic. Why?", "Plastic is a poor conductor, so the handle stays cooler", [W("Plastic is a good conductor, so heat leaves the handle quickly", "reversed", "Plastic is a poor conductor of heat."), W("Plastic expands more than metal does", "wrong-idea", "This is not the reason a handle is made of plastic."), W("Plastic is a good conductor, so it spreads heat to the food", "reversed", "Plastic is a poor conductor of heat.")], ["A poor conductor does not carry the heat to our hand."], None)
q("he-004", B, 1, HE, "What usually happens to a solid when it gains heat?", "It expands", [W("It contracts", "reversed", "A solid usually contracts when it loses heat."), W("It always melts", "wrong-idea", "Many solids expand without melting."), W("It always turns into a gas", "wrong-idea", "Most solids do not change into a gas when heated.")], ["Most solids expand when they gain heat."], None)
q("he-005", B, 1, HE, "A sealed balloon filled with air is left in the hot Sun. What happens to the air inside?", "It expands", [W("It contracts", "reversed", "Air contracts when it loses heat."), W("It becomes heavier", "wrong-idea", "Heating does not change the mass of the air."), W("It turns into a liquid", "wrong-idea", "Warm air does not turn into a liquid.")], ["A gas expands when it gains heat."], None)
q("he-006", B, 1, HE, "A metal lid is stuck tightly on a glass jar. Which of these will help loosen the lid?", "Running hot water over the lid", [W("Running cold water over the lid", "reversed", "Cold makes the lid contract and grip even more tightly."), W("Putting the whole jar into a freezer", "reversed", "Cold makes the lid contract and grip more tightly."), W("Pouring cold milk into the jar", "wrong-idea", "This does not make the lid any bigger.")], ["Heat makes the metal lid expand, so it becomes looser."], None)
q("he-007", B, 1, HE, "There are small gaps between the sections of a railway track. Why?", "So that the tracks have space to expand on hot days", [W("So that the tracks can contract more on hot days", "reversed", "Tracks expand, not contract, on hot days."), W("So that the trains can travel faster", "wrong-idea", "The gaps are not there to make trains faster."), W("So that rain can flow away", "wrong-idea", "The gaps are for expansion, not drainage.")], ["The tracks expand in the heat, and the gaps stop them from bending."], None)
q("he-008", B, 1, HE, "A thermometer is placed in hot water. What happens to the liquid inside it?", "It expands and rises up the tube", [W("It contracts and goes down the tube", "reversed", "The liquid contracts only when it loses heat."), W("It stays at the same level", "wrong-idea", "The liquid gains heat, so it changes."), W("It turns into a gas and escapes", "wrong-idea", "The liquid stays inside the tube.")], ["The liquid gains heat and expands, so it rises."], None)
q("he-009", B, 1, HE, "A thermometer is moved from warm water into ice water. What happens to the liquid inside it?", "It contracts and goes down the tube", [W("It expands and goes up the tube", "reversed", "The liquid expands only when it gains heat."), W("It stays at the same level", "wrong-idea", "The liquid loses heat, so it changes."), W("It freezes at once", "wrong-idea", "The liquid used in a thermometer does not freeze in ice water.")], ["The liquid loses heat and contracts."], None)
q("he-010", B, 2, HE, "Which of the following is a poor conductor of heat?", "A wooden block", [W("A copper coin", "wrong-material", "Copper is a metal, so it is a good conductor."), W("A steel nail", "wrong-material", "Steel is a metal, so it is a good conductor."), W("An iron rod", "wrong-material", "Iron is a metal, so it is a good conductor.")], ["Wood is a poor conductor of heat."], None)
q("he-011", B, 2, HE, "Why do people wear woollen clothes in cold places?", "Wool traps air, which is a poor conductor, so body heat is lost slowly", [W("Wool makes heat for the body", "wrong-idea", "Wool does not make heat."), W("Wool is a good conductor, so it brings heat to the body", "reversed", "Wool is a poor conductor."), W("Wool lets the cold air go into the body", "wrong-idea", "Cold does not flow in. Heat flows out of the body.")], ["Trapped air slows down the heat lost from the body."], None)
q("he-012", B, 1, HE, "What happens when ice gains heat at room temperature?", "It melts into water", [W("It freezes", "reversed", "Freezing happens when water loses heat."), W("It becomes colder", "wrong-idea", "Gaining heat makes it warmer, not colder."), W("It condenses", "wrong-term", "Condensation is a gas changing into a liquid.")], ["Ice melts when it gains heat."], None)
q("he-013", B, 1, HE, "What happens to water when it loses a lot of heat in a freezer?", "It freezes into ice", [W("It boils", "reversed", "Boiling happens when water gains heat."), W("It evaporates", "reversed", "Evaporation happens when water gains heat."), W("It turns into a gas", "reversed", "Water turns into a gas when it gains heat.")], ["Water freezes when it loses enough heat."], None)
q("he-014", B, 1, HE, "A metal ball can only just pass through a ring when both are cold. The ball is heated and then placed on the ring as shown. The ball does not pass through. Why?", "The heated ball has expanded", [W("The heated ball has contracted", "reversed", "Heat makes a solid expand."), W("The ring has become heavier", "wrong-idea", "The ring has not changed in mass."), W("The ball has become lighter", "wrong-idea", "Heating does not make the ball lighter.")], ["The ball gained heat and expanded, so it is too big for the ring."], lambda: ball_ring(False, "The heated ball and the ring"))
q("he-015", B, 1, HE, "A metal ball is just too big to pass through a ring. The ball is then cooled for a long time. What happens when it is put on the ring again?", "It passes through the ring", [W("It still cannot pass through the ring", "wrong-idea", "Cooling makes the ball contract."), W("It becomes too big for the ring", "reversed", "Cooling makes the ball smaller, not bigger."), W("It melts and sticks to the ring", "wrong-idea", "Cooling does not melt a metal.")], ["The cooled ball contracts, so it is small enough to pass."], None)
q("he-016", B, 2, HE, "Metal rods P, Q and R are heated at one end in the same way. The pins on the rods are stuck on with wax and fall off when the wax melts. Which rod is the best conductor of heat?", "P", [W("Q", "wrong-rod", "Only one pin fell from Q, so heat travelled slowly in it."), W("R", "wrong-rod", "No pin fell from R, so heat travelled the slowest in it."), W("They are all equally good", "wrong-idea", "The pins fell off at different times, so they are different.")], ["All the pins fell from P, so heat travelled furthest and fastest in P."], lambda: rods(["P", "Q", "R"], [3, 1, 0], "Rods with pins, in hot water"))
q("he-017", B, 2, HE, "In the same kind of test, rods A, B and C are heated at one end. Which rod is the poorest conductor of heat?", "A", [W("B", "wrong-rod", "Two pins fell from B, so heat travelled quite far in it."), W("C", "wrong-rod", "All pins fell from C, so it is the best conductor."), W("A and B", "wrong-rod", "Only A is the poorest, because no pin fell from it.")], ["No pin fell from A, so heat travelled the slowest in it."], lambda: rods(["A", "B", "C"], [0, 2, 3], "Rods with pins, in hot water"))
q("he-018", B, 2, HE, "The table shows the time taken for the wax on the end of each rod to melt when the other end was heated. Which two rods are the best conductors of heat?", "A and C", [W("B and D", "wrong-pair", "B and D took the longest time, so they are poor conductors."), W("A and B", "wrong-pair", "B took a long time, so it is a poor conductor."), W("C and D", "wrong-pair", "D took a long time, so it is a poor conductor.")], ["A shorter time means a better conductor of heat. A and C have the shortest times."], tb(["Rod", "Time for wax to melt (s)"], [["A", "12"], ["B", "85"], ["C", "9"], ["D", "70"]], [70, 190], "Four rods"))
q("he-019", B, 2, HE, "A cup has two plastic walls with a layer of air trapped between them. Why does this help to keep a hot drink hot?", "Air is a poor conductor, so heat escapes slowly", [W("Air is a good conductor, so it keeps the heat in", "reversed", "Air is a poor conductor of heat."), W("Air makes more heat for the drink", "wrong-idea", "Air does not make heat."), W("Air is heavy, so it keeps the cup steady", "wrong-idea", "This has nothing to do with heat.")], ["Trapped air is a poor conductor, so it slows the heat loss."], None)
q("he-020", B, 2, HE, "Which material is the best choice for the handle of a frying pan?", "Wood", [W("Copper", "wrong-material", "Copper is a good conductor, so the handle would get very hot."), W("Iron", "wrong-material", "Iron is a good conductor, so the handle would get very hot."), W("Aluminium", "wrong-material", "Aluminium is a good conductor, so the handle would get very hot.")], ["Wood is a poor conductor, so the handle stays cooler."], None)
q("he-021", B, 1, HE, "A wet cloth is hung in the Sun and becomes dry. What happens to the water in the cloth?", "It gains heat and evaporates into the air", [W("It loses heat and freezes", "reversed", "The Sun gives heat. The water does not lose heat."), W("It loses heat and condenses", "reversed", "Condensation happens when a gas loses heat."), W("It gains heat and melts", "wrong-term", "Melting is a solid becoming a liquid.")], ["The water gains heat from the Sun and changes into water vapour."], None)
q("he-022", B, 2, HE, "A metal spoon and a plastic spoon are placed in a bowl of hot soup. After a minute, which end of each spoon feels hotter?", "The top end of the metal spoon", [W("The top end of the plastic spoon", "reversed", "Plastic is a poor conductor, so its top end stays cooler."), W("Both feel equally hot", "wrong-idea", "Metal conducts heat much better than plastic."), W("Neither spoon becomes hot", "wrong-idea", "Metal conducts heat up the spoon to our hand.")], ["Heat travels up the metal spoon quickly because metal is a good conductor."], None)
q("he-023", B, 2, HE, "Which sentence about conductors of heat is correct?", "Metals are good conductors of heat", [W("Wood is a good conductor of heat", "reversed", "Wood is a poor conductor."), W("Air is a good conductor of heat", "reversed", "Air is a poor conductor."), W("Rubber is a good conductor of heat", "reversed", "Rubber is a poor conductor.")], ["Metals are good conductors; wood, air and rubber are poor conductors."], None)
q("he-024", B, 1, HE, "Overhead cables hang lower on a hot day than on a cold day. Why?", "The cables expand and become longer on a hot day", [W("The cables contract on a hot day", "reversed", "Cables expand when they gain heat."), W("The pull of gravity is stronger on a hot day", "wrong-idea", "Gravity does not change with the weather."), W("The poles become shorter on a hot day", "reversed", "Poles also expand when hot, they do not shrink.")], ["The cables gain heat and expand, so they sag."], None)
q("he-025", B, 2, HE, "An ice cube melts faster on a metal tray than on a plastic tray in the same room. Why?", "Metal conducts heat from the room to the ice faster", [W("Metal is a poor conductor, so it traps heat", "reversed", "Metal is a good conductor of heat."), W("Plastic is a good conductor of heat", "reversed", "Plastic is a poor conductor."), W("Metal makes its own heat", "wrong-idea", "Metal does not make heat.")], ["Metal is a better conductor, so heat reaches the ice faster."], None)

