q("he-108", I, 2, FT, "Rods of different materials are heated at one end to find which is the best conductor of heat. Which of these must be kept the same for every rod?", "The length and thickness of the rods", [W("The material of the rods", "changed-variable", "This is what is being tested."), W("The number of pins that fall off", "measured-variable", "This is the result that is measured."), W("The time at which each pin falls", "measured-variable", "This is a result, so it differs for each rod.")], ["Only the material should change."], None)
q("he-109", I, 2, HE, "A metal rod is heated at one end. Which statement describes how the heat travels?", "Heat travels along the rod from the hot end to the cooler end", [W("Heat travels from the cooler end to the hot end", "reversed", "Heat always flows from hot to cold."), W("Heat stays at the hot end", "wrong-idea", "Metal is a good conductor, so the heat moves along."), W("Heat travels only through the air around the rod", "wrong-idea", "Air is a poor conductor. Heat moves along the metal.")], ["Heat flows from the hotter part to the cooler part."], None)
CG = lambda: graph(["0", "5", "10", "15", "20"], [("P", [90, 80, 70, 60, 50]), ("Q", [90, 70, 50, 40, 30])], 100, "Time (min)", "Temperature (" + D + ")", "Two cups of hot water", ystep=10, W=360, H=250, legend="tr")
